 * Audit log helper.
 *
 * Writes to the audit_log table via the service-role client (bypasses RLS).
 * Every admin action, billing event, and sensitive data access should be logged here.
 *
 * Failures are logged but never throw — audit failures must not break the main flow.
 */
export async function logAuditAction(
  actorId: string | null,
  action: string,
  target: { type: string; id: string } | null,
  details: Json | null,
  studioId: string | null = null
): Promise<void> {
  try {
    // Lazy import to avoid circular deps and to keep this callable from edge runtimes
    const { createServiceRoleClient } = await import('./supabase/server')
    const supabase = createServiceRoleClient()

    await supabase.from('audit_log').insert({
      actor_id: actorId,
      action,
      target_type: target?.type ?? null,
      target_id: target?.id ?? null,
      studio_id: studioId,
      details,
    })
  } catch (err) {
    // Audit failures must not break the primary operation
    const { logger } = await import('./logger')
    logger.error({ err, action, actorId }, 'audit log write failed')
  }
